"""IDNA (Internationalized Domain Names) encoding and decoding.

Thin wrapper around the reference ``idna`` implementation, which follows
IDNA2008 (RFC 5890-5895) and Unicode UTS #46.

Two processing profiles are exposed:

* ``Profile.STRICT`` (default): UTS #46 nontransitional processing. This is
  what modern browsers, resolvers and registries use. Deviation characters are
  left intact (e.g. ``faß.de`` keeps the sharp s).
* ``Profile.TRANSITIONAL``: UTS #46 transitional processing for legacy
  IDNA2003 compatibility, which maps deviation characters (e.g. ``faß.de`` ->
  ``fass.de``).

Unicode is used at the public boundary: :func:`encode` accepts a Unicode
domain and returns the ASCII (A-label / punycode) form; :func:`decode` does
the reverse. Malformed input raises :class:`IDNAError`.
"""

from __future__ import annotations

from enum import Enum

import idna

__all__ = ["IDNAError", "Profile", "decode", "encode"]


class Profile(str, Enum):
    """UTS #46 processing profile."""

    STRICT = "strict"
    TRANSITIONAL = "transitional"


class IDNAError(ValueError):
    """Raised when a domain cannot be processed under the selected profile."""


def _options(profile: "Profile | str") -> dict:
    try:
        profile = Profile(profile)
    except ValueError as exc:
        raise IDNAError(f"unknown profile: {profile!r}") from exc

    return {
        "uts46": True,
        "transitional": profile is Profile.TRANSITIONAL,
        "std3_rules": True,
    }


def encode(domain: str, *, profile: "Profile | str" = Profile.STRICT) -> str:
    """Return the ASCII (A-label) form of an internationalized domain name.

    >>> encode("bücher.example")
    'xn--bcher-kva.example'
    """
    if not isinstance(domain, str):
        raise IDNAError("domain must be a str")
    try:
        return idna.encode(domain, **_options(profile)).decode("ascii")
    except idna.IDNAError as exc:
        raise IDNAError(str(exc)) from exc


def decode(domain: "str | bytes", *, profile: "Profile | str" = Profile.STRICT) -> str:
    """Return the Unicode (U-label) form of an ASCII/punycode domain name.

    >>> decode("xn--bcher-kva.example")
    'bücher.example'
    """
    if not isinstance(domain, (str, bytes)):
        raise IDNAError("domain must be str or bytes")
    try:
        return idna.decode(domain, **_options(profile))
    except idna.IDNAError as exc:
        raise IDNAError(str(exc)) from exc

from .cli import main

if __name__ == "__main__":
    raise SystemExit(main())

import pytest

from idnatool import IDNAError, Profile, decode, encode


def test_encode_unicode_to_alabel():
    assert encode("bücher.example") == "xn--bcher-kva.example"


def test_decode_alabel_to_unicode():
    assert decode("xn--bcher-kva.example") == "bücher.example"


def test_round_trip():
    domain = "例え.テスト"
    assert decode(encode(domain)) == domain


def test_ascii_passthrough():
    assert encode("example.com") == "example.com"


def test_strict_keeps_deviation_characters():
    assert encode("faß.de", profile=Profile.STRICT) == "xn--fa-hia.de"


def test_transitional_maps_deviation_characters():
    assert encode("faß.de", profile=Profile.TRANSITIONAL) == "fass.de"


def test_profile_accepts_plain_string():
    assert encode("bücher.example", profile="strict") == "xn--bcher-kva.example"


def test_invalid_domain_raises():
    with pytest.raises(IDNAError):
        encode("")
    with pytest.raises(IDNAError):
        encode("foo..bar")


def test_unknown_profile_raises():
    with pytest.raises(IDNAError):
        encode("example.com", profile="bogus")


def test_encode_rejects_bytes():
    with pytest.raises(IDNAError):
        encode(b"example.com")


def test_decode_accepts_bytes():
    assert decode(b"xn--bcher-kva.example") == "bücher.example"

from idnatool.cli import main


def test_cli_encode(capsys):
    assert main(["encode", "bücher.example"]) == 0
    assert capsys.readouterr().out.strip() == "xn--bcher-kva.example"


def test_cli_decode(capsys):
    assert main(["decode", "xn--bcher-kva.example"]) == 0
    assert capsys.readouterr().out.strip() == "bücher.example"


def test_cli_multiple_domains(capsys):
    assert main(["encode", "a.example", "bücher.example"]) == 0
    assert capsys.readouterr().out.splitlines() == [
        "a.example",
        "xn--bcher-kva.example",
    ]


def test_cli_profile_flag(capsys):
    assert main(["encode", "--profile", "transitional", "faß.de"]) == 0
    assert capsys.readouterr().out.strip() == "fass.de"


def test_cli_error_returns_nonzero(capsys):
    assert main(["encode", "foo..bar"]) == 1
    assert "idnatool:" in capsys.readouterr().err

